-- MeetU 演示数据：仅用于独立的空演示库。先启动 Spring Boot，让 Flyway 完成 V1-V6。
-- 可重复导入：固定 demo-* 主键，所有插入使用 ON CONFLICT DO NOTHING。
-- 所有时间以 UTC 写入；活动时间相对导入时刻，便于演示当日和近 7 日统计。
BEGIN;
DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM "User" WHERE id NOT LIKE 'demo-%')
     OR EXISTS (SELECT 1 FROM "Category" WHERE id NOT LIKE 'demo-%') THEN
    RAISE EXCEPTION '演示脚本只能导入空库或已导入演示数据的库';
  END IF;
END $$;
COMMIT;
